CREATE TABLE rule_transport_operation_mechanic(rule_id bigint PRIMARY KEY REFERENCES rule_rule(rule_id));
CREATE TABLE rule_transport_skill_capability(rule_id bigint NOT NULL REFERENCES rule_transport_operation_mechanic(rule_id),skill_rule_id bigint NOT NULL REFERENCES rule_skill(rule_id),target_kind text NOT NULL CHECK(target_kind IN('vehicle','ship')),maneuver_allowed boolean NOT NULL,routine_maintenance_allowed boolean NOT NULL,challenging_conditions_trigger_check boolean NOT NULL,can_hover boolean NOT NULL DEFAULT false,forward_motion_required boolean NOT NULL DEFAULT false,PRIMARY KEY(rule_id,skill_rule_id),CHECK(maneuver_allowed OR routine_maintenance_allowed));
COMMENT ON TABLE rule_transport_skill_capability IS 'CE-SKILL-017 paired-source spacecraft and vehicle operation boundaries; Riding is reserved for the animal-domain block.';
